            db.execute('DELETE FROM drafts WHERE actor_id=?',(actor['id'],))
            db.execute('DELETE FROM client_grants WHERE actor_id=?',(actor['id'],))
            db.execute('DELETE FROM sessions WHERE actor_id=?',(actor['id'],))
